{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.cut_size_analysis as ( WITH final_first_live_date AS ( select sku_group sku_group, status, live_date as live_date_final, price, category, sku_class from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by status desc) = 1 ), inventory AS ( SELECT upper(trim(\"Item SkuCode\")) AS sku, upper(trim(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), CHARINDEX(\'-\', REVERSE(\"Item SkuCode\")) + 1, LEN(\"Item SkuCode\"))))) AS sku_group, date, SUM(inventory) AS total_inventory FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility in (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\') GROUP BY upper(trim(\"Item SkuCode\")), upper(trim(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), CHARINDEX(\'-\', REVERSE(\"Item SkuCode\")) + 1, LEN(\"Item SkuCode\"))))), date ), price as ( select distinct sku_group, original_price as price from snitch_db.maplemonk.product_journey ), cost_price as ( select upper(trim(sku)) as sku, cost_price from snitch_db.maplemonk.sku_cost_price qualify row_number() over (partition by sku order by cost_price desc) = 1 ), Final_inventory_calculation as ( SELECT case when b.category in (\'Perfumes\',\'Accessories\',\'Sunglasses\',\'Bags\') then \'1\' else SPLIT_PART(a.sku, \'-\', -1) end AS size, a.sku, a.sku_group, a.total_inventory, a.date, b.live_date_final, b.category, b.sku_class, CASE WHEN b.live_date_final >= DATEADD(day, -60, CURRENT_DATE) THEN \'New\' ELSE b.sku_class END AS class FROM inventory a LEFT JOIN final_first_live_date b ON a.sku_group = b.sku_group GROUP BY case when b.category in (\'Perfumes\',\'Accessories\',\'Sunglasses\',\'Bags\') then \'1\' else SPLIT_PART(a.sku, \'-\', -1) end, a.sku, a.sku_group, a.total_inventory, b.live_date_final, b.category, b.sku_class, a.date ), total_size as ( select sku_group, date, count(sku_group) as total_size, count(case when total_inventory = 0 and size in (\'S\',\'M\',\'L\',\'XL\',\'30\',\'32\',\'34\',\'36\') then sku_group end) as cut_sizes, count(case when total_inventory = 0 then sku_group end) as final_cut_sizes, count(case when total_inventory >= 5 then sku_group end) as sizes_above_5, count(case when total_inventory >= 10 then sku_group end) as sizes_above_10, count(case when total_inventory >= 40 then sku_group end) as sizes_above_40, count(case when total_inventory < 5 and size in (\'S\',\'M\',\'L\',\'XL\',\'30\',\'32\',\'34\',\'36\') then sku_group end) as cut_sizes_below_5, count(case when total_inventory < 10 and size in (\'S\',\'M\',\'L\',\'XL\',\'30\',\'32\',\'34\',\'36\') then sku_group end) as cut_sizes_below_10 from Final_inventory_calculation group by 1,2 ), final_check as ( select a.*,b.total_size,b.cut_sizes,b.cut_sizes_below_10,b.final_cut_sizes,b.cut_sizes_below_5,b.sizes_above_5,b.sizes_above_10,b.sizes_above_40,c.price,d.cost_price from Final_inventory_calculation a left join total_size b on a.sku_group = b.sku_group and a.date = b.date LEFT JOIN PRICE C ON a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku where sku_class != \'4-New-Not-Sold\' ), inv_check as ( select date, sku_group, \'no_inv\' as type, sum(total_inventory) as inv from final_check group by 1,2,3 having sum(total_inventory) = 0 ), style as ( select sku_group, style from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc) = 1 ), cat_cut_size_pre as ( select a.*, coalesce(b.type,\'inv\') as inv_filter, c.style from final_check a left join inv_check b on a.sku_group = b.sku_group and a.date = b.date left join style c on a.sku_group = c.sku_group ), cat_cut_size as ( select category, date, sum(total_size) as cat_total_size, sum(cut_sizes) as cat_cut_sizes, sum(cut_sizes_below_10) as cat_cut_sizes_below_10, sum(cut_sizes_below_5) as cat_cut_sizes_below_5, sum(final_cut_sizes) as cat_final_cut_sizes, sum(sizes_above_5) as cat_sizes_above_5, sum(sizes_above_10) as cat_sizes_above_10, sum(sizes_above_40) as cat_sizes_above_40 from (select date, sku_group, category, inv_filter, max(total_size) as total_size, max(cut_sizes) as cut_sizes, max(cut_sizes_below_10) as cut_sizes_below_10, max(final_cut_sizes) as final_cut_sizes, max(cut_sizes_below_5) as cut_sizes_below_5, max(sizes_above_5) as sizes_above_5, max(sizes_above_10) as sizes_above_10, max(sizes_above_40) as sizes_above_40 from cat_cut_size_pre group by 1,2,3,4 ) where inv_filter = \'inv\' group by 1,2 ), sort_rank_pre as ( select a.*, cat_total_size, cat_cut_sizes, cat_cut_sizes_below_10, cat_cut_sizes_below_5, cat_final_cut_sizes, cat_sizes_above_5, cat_sizes_above_10, cat_sizes_above_40 from cat_cut_size_pre a left join cat_cut_size b on a.date = b.date and a.category = b.category ), sort_rank as ( select sku_group, sort_rank, global_sort_score from snitch_db.maplemonk.products_db_copy where status = \'active\' and sku_group is not null and sort_rank != 0 qualify row_number() over (partition by sku_group order by sort_rank asc) = 1 ) select a.*, b.sort_rank, b.global_sort_score from sort_rank_pre a left join sort_rank b on a.sku_group = b.sku_group ); create or replace table snitch_db.maplemonk.dod_all_channels_sku_inventory as ( WITH inv as ( select date, sku_group, sum(total_inventory)::INT as inv from cut_size_analysis where date >= \'2024-05-30\' group by 1,2 UNION ALL select date, SKU_GROUP, sum(inventory)::int AS INV from offline_master_daily_report_1 group by 1,2 ) SELECT DATE, SKU_GROUP, SUM(INV) as inv from inv group by 1,2 );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            